import testGlobsInStep from './test-globs-in-step.mjs';
import verifyShSourceDirs from './verify-sh-source-dirs.mjs';
import noStrayPackageJson from './no-stray-package-json.mjs';
import workerRestoresMain from './worker-restores-main.mjs';

// EdFringeNow's own local pack: project-specific working rules captured in this
// repo, layered on the shared Claudinite canon. Declaration-authoritative (no
// structural fingerprint). Its RULES.md is injected wherever this pack is declared,
// and its checks run against the tree.
export default {
  id: 'edfringe',
  ruleRoutingGuidance: {
    belongs: "EdFringeNow's own working rules — its build steps, shell scripts, and repo layout conventions",
    excludes: 'the edfringe.com scrape and the data layer it produces — those are edfringe-data',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [testGlobsInStep, verifyShSourceDirs, noStrayPackageJson, workerRestoresMain],
};

import lookupIndices from './lookup-indices.mjs';
import normalizerSelftestInVerify from './normalizer-selftest-in-verify.mjs';
import dataDirIsGeneratorOutput from './data-dir-is-generator-output.mjs';

// EdFringeNow's data-pipeline pack: the edfringe.com scrape and the committed
// data layer it produces (scraper/, data/). Split out of the general `edfringe`
// pack because it is a distinct domain with its own trigger — you are in it only
// when touching the scraper or the data files, not when working on the UI — and
// it is where this repo's external-API and wire-format knowledge lives.
// Declaration-authoritative like every local pack (no fingerprint).
export default {
  id: 'edfringe-data',
  ruleRoutingGuidance: {
    belongs: 'the edfringe.com scrape and the committed data layer it produces — external-API and wire-format knowledge',
    excludes: 'UI work and general repo working rules — those are edfringe',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [lookupIndices, normalizerSelftestInVerify, dataDirIsGeneratorOutput],
  skills: [],
};

// EdFringeNow's executable-requirements harness pack: the project-specific
// process elements the shared executable-requirements / spec-driven-product
// packs don't carry — the real-browser (Playwright) golden harness, the frozen
// fixture policy, and how golden approval runs in this repo. Work procedure
// only; product behaviour belongs in product/requirements.md.
export default {
  id: 'edfringe-requirements',
  ruleRoutingGuidance: {
    belongs:
      "the executable-requirements harness of this repo: the Playwright golden lanes, browser-determinism recipe, fixture freeze, and the golden-approval procedure's local mechanics",
    excludes:
      'product behaviour (product/requirements.md and its cases); general repo working rules — edfringe; the data pipeline — edfringe-data',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
};

